import{_ as t}from"./chunks/home-estop.pc.en.BSpMx1St.js";import{_ as o}from"./chunks/emo.CGwrrK0y.js";import{_ as a}from"./chunks/home-status.pc.en.KhsLj-pc.js";import{_ as n,o as i,c as r,a5 as s}from"./chunks/framework.D47SInms.js";const w=JSON.parse('{"title":"Emergency Stop","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/emergency.md","filePath":"manual/gui/emergency.md","lastUpdated":1791600043000}'),c={name:"manual/gui/emergency.md"};function d(h,e,l,p,m,u){return i(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="emergency-stop" tabindex="-1">Emergency Stop <a class="header-anchor" href="#emergency-stop" aria-label="Permalink to &quot;Emergency Stop&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Always keep the emergency stop button accessible during operation. In any situation where the robot poses a risk to people or property, press the emergency stop button immediately.</p></div><h2 id="e-stop-in-the-app" tabindex="-1">E-STOP in the app <a class="header-anchor" href="#e-stop-in-the-app" aria-label="Permalink to &quot;E-STOP in the app&quot;">​</a></h2><p><img src="'+t+'" alt="E-STOP confirmation"></p><p>The red <code>E-STOP</code> button sits at the right of the top bar on the control home. On a very small screen, less than 720 px wide, it shows only its emergency icon (on a humanoid the <code>RL stop</code> label stays). On the other screens it sits at the right of the header, whenever a robot is connected or is reconnecting after a dropped link — it still works for 8 seconds after the drop. Pressing it opens the confirmation <code>Emergency stop?</code>:</p><blockquote><p>The robot immediately stops all motion and cuts power. Reinitialization is required to resume control.</p></blockquote><p>Press <code>Stop</code> to send the emergency stop, or <code>Cancel</code> to close the dialog. There is no path that fires E-STOP without this confirmation.</p><ul><li>The app sends the emergency stop on a dedicated channel, ahead of anything already queued, and repeats it on the reliable command channel.</li><li>You do not need to own the robot first: the robot accepts E-STOP from any connected device, bypassing the ownership check. It does not take ownership — the current owner stays the same.</li><li>If the robot does not acknowledge the command, the app logs <code>E-Stop send failed — no response. Use the physical E-Stop</code>. Do not wait — use the physical button.</li></ul><h2 id="physical-emergency-stop-button" tabindex="-1">Physical emergency stop button <a class="header-anchor" href="#physical-emergency-stop-button" aria-label="Permalink to &quot;Physical emergency stop button&quot;">​</a></h2><figure><img src="'+o+'" alt="Emergency stop button on the rear of the robot"><figcaption style="text-align:center;">[ Emergency stop push button — located on the rear of the robot ]</figcaption></figure><p>When the physical <strong>emergency stop button</strong> is pressed, or the app&#39;s <code>E-STOP</code> is confirmed:</p><ul><li>All joints switch to <strong>High Damping</strong> mode.</li><li>The robot resists external motion but does <strong>not</strong> accept torque or position commands.</li><li>The robot may lose its posture and settle to the ground under gravity.</li></ul><p>High Damping mode protects both the user and the robot. The robot will not execute any motion commands until the emergency stop is cleared and the robot is re-initialized.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><ol><li><strong>Ensure safety</strong> — confirm that all people and animals are at least 2 m from the robot.</li><li><strong>Release the button</strong> — if the physical button was pressed, rotate it clockwise to unlock it.</li><li><strong>Return to initial pose</strong> — if the robot has fallen or shifted, place it in the <a href="/RBQ/nightly/manual/operation/initial-pose.html">initial pose</a> on a flat surface. Do not force the joints while the robot is in High Damping mode.</li><li><strong>Re-initialize</strong> — run the automatic start sequence or the Stand motion from the <a href="/RBQ/nightly/manual/gui/control-home.html">control home</a> and confirm the robot state in the top bar before resuming operation.</li></ol><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#emergency">Developer mode</a>.</p></blockquote><h2 id="spectating" tabindex="-1">Spectating <a class="header-anchor" href="#spectating" aria-label="Permalink to &quot;Spectating {#spectating}&quot;">​</a></h2><p>Only one device controls the robot at a time. If you are connected while another app or controller holds ownership, after about a second this device switches to spectating: the video and the 3D view keep running, but every control below the top bar is locked. The top bar stays usable — <code>E-STOP</code>, the view dropdown and the status popover. The <code>Spectating</code> button sits just below it at the center, next to <code>Another device is driving · tap to take control</code>.</p><p>On the hub, in <code>Settings</code> and in the log nothing is covered. On the hub the <code>Dashboard</code> and <code>Maintenance</code> tiles are locked and the auto-start card is hidden; in <code>Settings</code> the robot tabs are locked while the app tabs stay usable. The <code>Spectating</code> button still appears below the top bar.</p><p>While spectating, the view dropdown offers <code>3D</code> and <code>Driver&#39;s view</code> only. The driving device picks the camera, so <code>Driver&#39;s view</code> shows the same camera it is watching. When the driving device is on <code>3D</code>, <code>Driver&#39;s view</code> switches to 3D as well, and goes back to that camera when the driver does. A spectating device never turns the robot&#39;s camera on or changes it. You hear the robot&#39;s audio only while the driving device has <code>Listen to robot audio</code> on.</p><p>Up to four devices can spectate a robot at once (<code>MAX_SPECTATORS</code> under <code>[WebRTC]</code> in the robot&#39;s <code>Streamer.ini</code>, 4 when absent, <code>0</code> for no limit; read when Streamer starts). When all slots are taken, a spectator gets no video until one frees up: the view stays on <code>3D</code> and the <code>Spectating</code> button reads <code>Too many viewers, video waiting · tap to take control</code>. Video comes back on its own when a slot frees up, and taking control works regardless. A spectator connected remotely (WAN) gets no video, only the 3D view and status readouts.</p><p>Tap <code>Spectating</code> to open <code>Take control?</code>:</p><ul><li><code>Take control</code> — asks the robot to hand ownership to this device. The device that was driving switches to spectating.</li><li><code>▶ Auto Start</code> — after the confirmation <code>Run Auto Start?</code> → <code>Auto Start</code>, takes control and runs the automatic start sequence.</li><li><code>Keep spectating</code> — closes the menu.</li></ul><p>On the control home you can also check and take ownership from the <code>Overall system status</code> popover (tap the status chip in the top bar): the <code>Ownership</code> row shows <code>Held</code> when this device is the owner and <code>Take ▸</code> when it is not.</p><p><img src="'+a+'" alt="Overall system status popover with the Ownership row"></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions.html">General Safety Guidelines</a></li><li><a href="/RBQ/nightly/manual/safety/emergency-stop-procedures.html">Emergency Stop Procedures (detailed)</a></li></ul>',27)])])}const v=n(c,[["render",d]]);export{w as __pageData,v as default};
